    "organizationId" TEXT NOT NULL,
    "projectId" TEXT NOT NULL,
    "taskId" TEXT NOT NULL,
    "reason" "NeedsYouReason" NOT NULL,
    "audience" "NeedsYouAudience" NOT NULL,
    "state" "NeedsYouState" NOT NULL DEFAULT 'open',
    "approvalId" TEXT,
    "summary" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "resolvedAt" TIMESTAMP(3),
    "resolvedByMemberId" TEXT,

    CONSTRAINT "needs_you_item_pkey" PRIMARY KEY ("id")
);

