ALTER TABLE "needs_you_item" ADD CONSTRAINT "needs_you_item_approvalId_taskId_fkey" FOREIGN KEY ("approvalId", "taskId") REFERENCES "approval"("id", "taskId") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "webhook_delivery" ADD CONSTRAINT "webhook_delivery_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "organization"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "webhook_delivery" ADD CONSTRAINT "webhook_delivery_connectionId_organizationId_fkey" FOREIGN KEY ("connectionId", "organizationId") REFERENCES "connection"("id", "organizationId") ON DELETE CASCADE ON UPDATE CASCADE;


-- ===========================================================================
-- ostra: raw SQL that Prisma can't declare. Prisma Migrate doesn't read check constraints, and
-- never sees the `ostra_live` schema, so a later `migrate dev` leaves all of this alone.
-- ===========================================================================

-- The install has one settings row.
ALTER TABLE "instance_setting" ADD CONSTRAINT "instance_setting_one_row" CHECK ("id" = 'instance');

-- A membership is an admin or a member (Q35, F-003).
ALTER TABLE "member" ADD CONSTRAINT "member_role_check" CHECK ("role" IN ('admin', 'member'));

-- A personal runner belongs to one member and no pool; a pool runner to a pool and no member (ADR 0029).
ALTER TABLE "runner" ADD CONSTRAINT "runner_kind_owner_check" CHECK (
  ("kind" = 'personal' AND "ownerMemberId" IS NOT NULL AND "poolId" IS NULL)
  OR ("kind" = 'pool' AND "poolId" IS NOT NULL AND "ownerMemberId" IS NULL)
);
ALTER TABLE "runner" ADD CONSTRAINT "runner_capacity_check" CHECK ("capacity" > 0);

-- A task's state columns hold one state of the domain's union (packages/domain, lifecycles/mapping.ts).
ALTER TABLE "task" ADD CONSTRAINT "task_sub_state_only_in_review" CHECK (("state" = 'in_review') = ("subState" IS NOT NULL));
ALTER TABLE "task" ADD CONSTRAINT "task_needs_you_reason_only_in_needs_you" CHECK (("state" = 'needs_you') = ("needsYouReason" IS NOT NULL));
ALTER TABLE "task" ADD CONSTRAINT "task_stopped_reason_only_in_stopped" CHECK (("state" = 'stopped') = ("stoppedReason" IS NOT NULL));
-- Only a code task is in review or merged; only a refine or review task is done (ADR 0028).
ALTER TABLE "task" ADD CONSTRAINT "task_code_states" CHECK ("state" NOT IN ('in_review', 'merged') OR "kind" = 'code');
ALTER TABLE "task" ADD CONSTRAINT "task_done_states" CHECK ("state" <> 'done' OR "kind" IN ('refine', 'review'));
ALTER TABLE "task" ADD CONSTRAINT "task_prompt_source" CHECK ("source" <> 'prompt' OR "prompt" IS NOT NULL);
ALTER TABLE "task" ADD CONSTRAINT "task_ticket_source" CHECK ("source" <> 'ticket' OR "ticketKey" IS NOT NULL);
ALTER TABLE "task" ADD CONSTRAINT "task_counters_check" CHECK ("eventSeq" >= 0 AND "leaseEpoch" >= 0);

-- A session's outcome is set exactly when it ended.
ALTER TABLE "session" ADD CONSTRAINT "session_outcome_only_when_ended" CHECK (("state" = 'ended') = ("outcome" IS NOT NULL));

-- Each kind of environment entry has its own fields (F-050).
ALTER TABLE "environment_entry" ADD CONSTRAINT "environment_entry_kind_fields" CHECK (
  ("kind" = 'variable' AND "name" IS NOT NULL AND "path" IS NULL AND "value" IS NOT NULL AND "secretRef" IS NULL)
  OR ("kind" = 'secret' AND "name" IS NOT NULL AND "path" IS NULL AND "value" IS NULL AND "secretRef" IS NOT NULL)
  OR ("kind" = 'file' AND "name" IS NULL AND "path" IS NOT NULL AND "value" IS NOT NULL AND "secretRef" IS NULL)
);

-- Event, lease and command numbers start at 1 (ADR 0034, ADR 0035).
ALTER TABLE "event" ADD CONSTRAINT "event_numbers_check" CHECK ("seq" > 0 AND ("sessionSeq" IS NULL OR "sessionSeq" > 0));
ALTER TABLE "lease" ADD CONSTRAINT "lease_epoch_check" CHECK ("epoch" > 0);
ALTER TABLE "command" ADD CONSTRAINT "command_seq_check" CHECK ("seq" > 0);

-- An approval's fields follow its state (domain-model.md, "An approval's lifecycle").
ALTER TABLE "approval" ADD CONSTRAINT "approval_state_fields" CHECK (
  ("state" = 'open' AND "decision" IS NULL AND "ruleId" IS NULL AND "closedReason" IS NULL)
  OR ("state" = 'answered' AND "decision" IS NOT NULL AND "optionId" IS NOT NULL AND "answeredByMemberId" IS NOT NULL)
  OR ("state" = 'answered_by_rule' AND "decision" IS NOT NULL AND "ruleId" IS NOT NULL)
  OR ("state" = 'closed' AND "closedReason" IS NOT NULL)
);

-- Partial text (ADR 0035): the latest accumulated text of each open segment. UNLOGGED, never in
-- the log, deleted when the segment's completed message commits. Its own schema keeps it out of
-- Prisma's sight (see the top of schema.prisma).
CREATE SCHEMA IF NOT EXISTS "ostra_live";

CREATE UNLOGGED TABLE "ostra_live"."live_text" (
  "taskId" TEXT NOT NULL,
  "segmentId" TEXT NOT NULL,
  "organizationId" TEXT NOT NULL,
  "projectId" TEXT NOT NULL,
  "sessionId" TEXT NOT NULL,
  "turnId" TEXT NOT NULL,
  "kind" TEXT NOT NULL CHECK ("kind" IN ('message', 'thought')),
  "text" TEXT NOT NULL,
  "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY ("taskId", "segmentId")
);
